import fs from 'node:fs';
import path from 'node:path';
const root='skills/escape-analysis-internals';
const walk=dir=>fs.readdirSync(dir,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(path.join(dir,e.name)):[path.join(dir,e.name)]);
const markdown=walk(root).filter(p=>p.endsWith('.md'));const links=[];
for(const file of markdown){const text=fs.readFileSync(file,'utf8');for(const match of text.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)){const target=match[1].split('#')[0];if(!target||/^[a-z][a-z\d+.-]*:/i.test(target))continue;const resolved=path.resolve(path.dirname(file),target);if(!fs.existsSync(resolved))throw Error(file+': '+target);links.push({file,target});}}
console.log(JSON.stringify({markdownFiles:markdown.length,relativeLinks:links.length,links},null,2));
